def even_binomial_Coeff_Sum(n):
    if n == 0:
        return 0
    total = 0
    for i in range(0, n + 1, 2):
        # Compute C(n, i) = n! / (i! * (n-i)!)
        C = 1
        for j in range(1, i + 1):
            C = C * (n - i + j) // j
        total += C
    return total
