def count_binary_seq(n):
    if n == 0:
        return 1
    # This is a known combinatorial problem where the answer is given by the central binomial coefficient multiplied by 2^(n-1)
    # The central binomial coefficient C(2n-1, n-1) multiplied by 2^(n-1) gives the desired count.
    # Using dynamic programming to compute the binomial coefficient efficiently
    binom = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        for j in range(i + 1):
            if j == 0 or j == i:
                binom[i][j] = 1
            else:
                binom[i][j] = binom[i-1][j-1] + binom[i-1][j]

    res = binom[2*n - 1][n - 1] * (2 ** (n - 1))
    return res
